1	import { createClient } from "@/lib/supabase/server";
2	import { REPORT_TIMEZONE, getPeriodRange, parsePeriod } from "../../reports/period";
3	
4	function csvEscape(v: string | number | null | undefined) {
5	  const s = String(v ?? "");
6	  return s.includes(",") || s.includes('"') || s.includes("\n")
7	    ? `"${s.replace(/"/g, '""')}"`
8	    : s;
9	}
10	
11	function toCsv(rows: (string | number)[][]) {
12	  return rows.map((r) => r.map(csvEscape).join(",")).join("\r\n");
13	}
14	
15	function fmtDate(iso: string) {
16	  return new Date(iso).toLocaleDateString("id-ID", {
17	    day: "2-digit",
18	    month: "2-digit",
19	    year: "numeric",
20	    timeZone: REPORT_TIMEZONE,
21	  });
22	}
23	
24	function fmtTime(iso: string) {
25	  return new Date(iso).toLocaleTimeString("id-ID", {
26	    hour: "2-digit",
27	    minute: "2-digit",
28	    second: "2-digit",
29	    timeZone: REPORT_TIMEZONE,
30	  });
31	}
32	
33	const hourFormatter = new Intl.DateTimeFormat("en-US", {
34	  hour: "numeric",
35	  hourCycle: "h23",
36	  timeZone: REPORT_TIMEZONE,
37	});
38	
39	function wibHour(iso: string) {
40	  return Number(hourFormatter.format(new Date(iso)));
41	}
42	
43	type TxRow = {
44	  id: string;
45	  invoice_number: string;
46	  date: string;
47	  subtotal: number;
48	  service: number;
49	  tax: number;
50	  total: number;
51	  payment_method: string;
52	  received: number | null;
53	  change: number;
54	  is_holiday: boolean;
55	  voided: boolean;
56	  cashiers: { name: string } | null;
57	  members: { name: string } | null;
58	};
59	
60	export async function GET(
61	  request: Request,
62	  { params }: { params: Promise<{ businessId: string }> },
63	) {
64	  const { businessId } = await params;
65	  const url = new URL(request.url);
66	  const typeParam = url.searchParams.get("type");
67	  const type = typeParam === "tickets" || typeParam === "hourly" ? typeParam : "transactions";
68	  const period = parsePeriod(url.searchParams.get("period") ?? undefined);
69	  const { fromIso, toIsoExclusive } = getPeriodRange(
70	    period,
71	    url.searchParams.get("from") ?? undefined,
72	    url.searchParams.get("to") ?? undefined,
73	  );
74	  const categoryFilter = url.searchParams.get("category") ?? undefined;
75	  const serialFrom = url.searchParams.get("serialFrom") ?? undefined;
76	  const serialTo = url.searchParams.get("serialTo") ?? undefined;
77	
78	  const supabase = await createClient();
79	
80	  const { data: business } = await supabase
81	    .from("businesses")
82	    .select("id")
83	    .eq("id", businessId)
84	    .single();
85	
86	  if (!business) {
87	    return new Response("Not found", { status: 404 });
88	  }
89	
90	  let txQuery = supabase
91	    .from("ticket_transactions")
92	    .select(
93	      "id, invoice_number, date, subtotal, service, tax, total, payment_method, received, change, is_holiday, voided, cashiers!ticket_transactions_cashier_id_fkey(name), members(name)",
94	    )
95	    .eq("business_id", businessId)
96	    .order("date", { ascending: true });
97	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
98	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
99	  const { data: txData } = await txQuery;
100	  const txList = ((txData ?? []) as unknown as TxRow[]) ?? [];
101	
102	  let rows: (string | number)[][];
103	  let filename: string;
104	  const periodLabel =
105	    period === "today" ? fmtDate(new Date().toISOString()).replace(/\//g, "-") : period;
106	
107	  if (type === "transactions") {
108	    rows = [
109	      [
110	        "No. Invoice",
111	        "Tanggal",
112	        "Jam",
113	        "Kasir",
114	        "Member",
115	        "Hari",
116	        "Subtotal",
117	        "Layanan",
118	        "Pajak",
119	        "Total",
120	        "Metode Bayar",
121	        "Diterima",
122	        "Kembalian",
123	        "Status",
124	      ],
125	    ];
126	    for (const tx of txList) {
127	      rows.push([
128	        tx.invoice_number,
129	        fmtDate(tx.date),
130	        fmtTime(tx.date),
131	        tx.cashiers?.name ?? "",
132	        tx.members?.name ?? "",
133	        tx.is_holiday ? "Libur" : "Kerja",
134	        Number(tx.subtotal),
135	        Number(tx.service),
136	        Number(tx.tax),
137	        Number(tx.total),
138	        tx.payment_method,
139	        tx.received !== null ? Number(tx.received) : "",
140	        Number(tx.change),
141	        tx.voided ? "Dibatalkan" : "Sukses",
142	      ]);
143	    }
144	    filename = `TiketTransaksi_${periodLabel}.csv`;
145	  } else {
146	    const txMap = new Map(txList.map((t) => [t.id, t]));
147	    const txIds = Array.from(txMap.keys());
148	
149	    let serials: {
150	      id: string;
151	      serial_no: number;
152	      manual_number: string;
153	      price: number;
154	      is_member_price: boolean;
155	      ticket_transaction_id: string;
156	      ticket_categories: { name: string } | null;
157	    }[] = [];
158	
159	    if (txIds.length > 0) {
160	      let serialQuery = supabase
161	        .from("ticket_serials")
162	        .select(
163	          "id, serial_no, manual_number, price, is_member_price, ticket_transaction_id, ticket_categories(name)",
164	        )
165	        .in("ticket_transaction_id", txIds)
166	        .order("serial_no", { ascending: true });
167	      if (categoryFilter) serialQuery = serialQuery.eq("ticket_category_id", categoryFilter);
168	      if (serialFrom) serialQuery = serialQuery.gte("serial_no", Number(serialFrom));
169	      if (serialTo) serialQuery = serialQuery.lte("serial_no", Number(serialTo));
170	      const { data } = await serialQuery;
171	      serials = (data ?? []) as unknown as typeof serials;
172	    }
173	
174	    const ticketRows = serials
175	      .map((s) => ({ ...s, tx: txMap.get(s.ticket_transaction_id) }))
176	      .filter((s) => s.tx !== undefined) as (typeof serials[number] & { tx: TxRow })[];
177	
178	    if (type === "tickets") {
179	      rows = [
180	        [
181	          "No. Invoice",
182	          "Tanggal",
183	          "Jam",
184	          "No. Seri",
185	          "No. Tiket Manual",
186	          "Kategori",
187	          "Harga",
188	          "Member?",
189	          "Status",
190	        ],
191	      ];
192	      for (const r of ticketRows) {
193	        rows.push([
194	          r.tx.invoice_number,
195	          fmtDate(r.tx.date),
196	          fmtTime(r.tx.date),
197	          r.serial_no,
198	          r.manual_number,
199	          r.ticket_categories?.name ?? "",
200	          Number(r.price),
201	          r.is_member_price ? "Ya" : "Tidak",
202	          r.tx.voided ? "Dibatalkan" : "Sukses",
203	        ]);
204	      }
205	      filename = `TiketPerUnit_${periodLabel}.csv`;
206	    } else {
207	      const hourly = new Map<number, { qty: number; revenue: number }>();
208	      for (const r of ticketRows) {
209	        if (r.tx.voided) continue;
210	        const h = wibHour(r.tx.date);
211	        const entry = hourly.get(h) ?? { qty: 0, revenue: 0 };
212	        entry.qty += 1;
213	        entry.revenue += Number(r.price);
214	        hourly.set(h, entry);
215	      }
216	      rows = [["Jam", "Jumlah Tiket", "Pendapatan"]];
217	      for (let h = 0; h < 24; h++) {
218	        const entry = hourly.get(h);
219	        if (!entry) continue;
220	        rows.push([`${String(h).padStart(2, "0")}:00`, entry.qty, entry.revenue]);
221	      }
222	      filename = `TiketPerJam_${periodLabel}.csv`;
223	    }
224	  }
225	
226	  // BOM (U+FEFF) supaya Excel membuka file sebagai UTF-8.
227	  return new Response(String.fromCharCode(0xfeff) + toCsv(rows), {
228	    headers: {
229	      "Content-Type": "text/csv; charset=utf-8",
230	      "Content-Disposition": `attachment; filename="${filename}"`,
231	    },
232	  });
233	}
